class BinarySearchTree:
    """Class for BST"""

    def __init__(self):
        """Initialising a BST"""
        self.root = None

    def insert(self, val):
        """Creating a BST with root value as val"""
        # Check if tree has root with None value
        if self.root is None:
            self.root = Node(val)
        # Here the tree already has one root
        else:
            current = self.root
            while True:
                if val < current.info:
                    if current.left:
                        current = current.left
                    else:
                        current.left = Node(val)
                        break
                elif val > current.info:
                    if current.right:
                        current = current.right
                    else:
                        current.right = Node(val)
                        break
                else:
                    break

    def search(self, val, to_delete=False):
        current = self.root
        prev = -1
        while current:
            if val < current.info:
                prev = current
                current = current.left
            elif val > current.info:
                prev = current
                current = current.right
            elif current.info == val:
                if not to_delete:
                    return "Match Found"
                return prev
            else:
                break
        if not to_delete:
            return "Not Found"

    # Method to delete a tree-node if it exists, else error message will be returned.
    def delete(self, val):
        prev = self.search(val, True)
        # Check if node exists
        if prev is not None:
